{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket is missing a Public Access block, which could lead to unintended public access to the bucket."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have versioning enabled, which could result in data loss if objects are accidentally deleted or overwritten."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"changeme_aws_s3_bucket_backend_simple\" {\n  force_destroy = true\n  bucket        = \"changeme-${random_id.changeme_backends_s3_bucket_name.hex}\"\n}\n\nresource \"aws_s3_bucket_versioning\" \"changeme_aws_s3_bucket_backend_simple_versioning\" {\n  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id\n  versioning_configuration {\n    status = \"Enabled\"\n  }\n}\n\nresource \"aws_s3_bucket_public_access_block\" \"changeme_aws_s3_bucket_backend_simple_public_access_block\" {\n  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id\n\n  block_public_acls   = true\n  block_public_policy = true\n  ignore_public_acls  = true\n  restrict_public_buckets = true\n}",
  "fix_summary": "Added aws_s3_bucket_versioning and aws_s3_bucket_public_access_block resources to enable versioning and block public access to the S3 bucket."
}
